import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"崧高","description":"","frontmatter":{"title":"崧高","date":"2026-11-09T00:00:00.000Z","seq":25,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/崧高.md","filePath":"blogs/诗经·大雅/崧高.md"}'),p={name:"blogs/诗经·大雅/崧高.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="崧高" tabindex="-1">崧高 <a class="header-anchor" href="#崧高" aria-label="Permalink to &quot;崧高&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">崧高维岳，骏极于天。维岳降神，生甫及申。维申及甫，维周之翰。四国于蕃。四方于宣。</p><p class="poem-stanza">亹亹申伯，王缵之事。于邑于谢，南国是式。王命召伯，定申伯之宅。登是南邦，世执其功。</p><p class="poem-stanza">王命申伯，式是南邦。因是谢人，以作尔庸。王命召伯，彻申伯土田。王命傅御，迁其私人。</p><p class="poem-stanza">申伯之功，召伯是营。有俶其城，寝庙既成。既成藐藐，王锡申伯。四牡蹻蹻，钩膺濯濯。</p><p class="poem-stanza">王遣申伯，路车乘马。我图尔居，莫如南土。锡尔介圭，以作尔宝。往近王舅，南土是保。</p><p class="poem-stanza">申伯信迈，王饯于郿。申伯还南，谢于诚归。王命召伯，彻申伯土疆。以峙其粻，式遄其行。</p><p class="poem-stanza">申伯番番，既入于谢。徒御啴啴。周邦咸喜，戎有良翰。不显申伯，王之元舅，文武是宪。</p><p class="poem-stanza">申伯之德，柔惠且直。揉此万邦，闻于四国。吉甫作诵，其诗孔硕。其风四好，以赠申伯。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
